#include <stdio.h>
int main(void) {
  int total = 7;
  int count = 2;
  int integer_average = total / count;
  double precise = (double)total / count;
  printf("integer=%d\n", integer_average);
  printf("precise=%.2f\n", precise);
  return 0;
}

